begin;
do $$declare q record;rid uuid;action1 uuid;action2 uuid;action3 uuid;narration1 uuid;narration2 uuid;data jsonb;request jsonb;denied boolean;begin
 select d.owner_id,d.monkey_id,(select id from auth.users where is_anonymous and id not in(select monkey_id from private.monkey_delegations) and id not in(select user_id from private.portal_accounts) limit 1) as player_user into q from private.monkey_delegations d where revoked_at is null and owner_id in(select user_id from private.portal_admins) limit 1;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',q.monkey_id,'role','authenticated')::text,true);
 data:=public.create_prepared_room(gen_random_uuid(),'__QA Message Menu','QA Menu','Day','Morning','mountain-path','','','A stone path.','Explore',array[]::uuid[]);rid:=(data->>'id')::uuid;
 update public.room_members set allowed_characters=array['QA Menu','QA Second'] where room_id=rid and role='owner';
 insert into public.room_members(room_id,user_id,character_name,role,allowed_characters) values(rid,q.player_user,'QA Guest','member',array['QA Guest']);
 action1:=public.post_character_as_owner(rid,'I look.','player',gen_random_uuid(),'QA Menu');update public.messages set created_at=clock_timestamp() where id=action1;
 assert public.manage_hud_messages(rid,array[action1],'speaker','player','QA Second')=1;
 assert (select character_name='QA Second' and sender_id=q.owner_id from public.messages where id=action1),'speaker did not preserve author';
 assert public.manage_hud_messages(rid,array[action1],'speaker','ooc',null)=1;
 denied:=false;begin perform public.prepare_hud_narration(rid);exception when others then denied:=true;end;assert denied,'OOC became pending action';
 assert public.manage_hud_messages(rid,array[action1],'speaker','player',null)=1;
 denied:=false;begin perform public.manage_hud_messages(rid,array[action1],'speaker','player','Not participating');exception when others then denied:=true;end;assert denied,'invalid speaker accepted';
 narration1:=public.publish_as_owner(rid,'A traveller gives you an apple. [PATHS_STATE]{"version":1,"inventory":[{"character":"QA Second","item":"Apple","delta":1}],"scenes":[]}[/PATHS_STATE]',action1);update public.messages set created_at=clock_timestamp() where id=narration1;
 assert public.manage_hud_messages(rid,array[narration1],'delete')=1;
 assert (public.room_player_panel(rid,'QA Second')->'inventory'->0->>'quantity')::int=1,'deletion undid inventory';
 denied:=false;begin perform public.prepare_hud_narration(rid);exception when others then denied:=true;end;assert denied,'hidden narration reopened processed actions';
 denied:=false;begin perform public.manage_hud_messages(rid,array[narration1],'speaker','ooc');exception when others then denied:=true;end;assert denied,'narrator identity changed';
 assert public.manage_hud_messages(rid,array[narration1],'restore')=1;
 assert (public.room_player_panel(rid,'QA Second')->'inventory'->0->>'quantity')::int=1,'restore replayed inventory';
 action2:=public.post_character_as_owner(rid,'I wait.','player',gen_random_uuid(),'QA Menu');update public.messages set created_at=clock_timestamp() where id=action2;
 action3:=public.post_character_as_owner(rid,'I wave.','player',gen_random_uuid(),'QA Menu');update public.messages set created_at=clock_timestamp() where id=action3;
 request:=public.prepare_hud_narration(rid);
 assert public.manage_hud_messages(rid,array[action3],'delete')=1;
 denied:=false;begin perform public.publish_hud_narration((request->>'request_id')::uuid,'The traveller waits. [PATHS_STATE]{"version":1,"inventory":[],"scenes":[]}[/PATHS_STATE]');exception when others then denied:=true;end;assert denied,'deleted action accepted stale narration';
 request:=public.prepare_hud_narration(rid);assert jsonb_array_length(request->'context'->'actions')=1;
 narration2:=public.publish_hud_narration((request->>'request_id')::uuid,'The traveller waits. [PATHS_STATE]{"version":1,"inventory":[],"scenes":[]}[/PATHS_STATE]');
 assert (select status='applied' from private.narration_state_receipts where message_id=narration2),'deleted latest player blocked publisher';
 -- A player may manage own pending messages, never another participant or a narrator.
 perform set_config('request.jwt.claims',jsonb_build_object('sub',q.player_user,'role','authenticated')::text,true);
 denied:=false;begin perform public.manage_hud_messages(rid,array[narration2],'delete');exception when others then denied:=true;end;assert denied,'player deleted narrator';
 denied:=false;begin perform public.manage_hud_messages(rid,array[action1],'speaker','ooc');exception when others then denied:=true;end;assert denied,'player changed other author';
 insert into public.messages(room_id,sender_id,character_name,kind,body,created_at) values(rid,q.player_user,'QA Guest','player','I listen.',clock_timestamp()) returning id into action3;
 assert public.manage_hud_messages(rid,array[action3],'speaker','ooc')=1;
 assert public.manage_hud_messages(rid,array[action3],'delete')=1;
 assert public.manage_hud_messages(rid,array[action3],'restore')=1;
 denied:=false;begin perform public.manage_hud_messages(rid,array[action3],'speaker','player','QA Menu');exception when others then denied:=true;end;assert denied,'player reassigned another character';
 assert not has_function_privilege('anon','public.manage_hud_messages(uuid,uuid[],text,text,text)','execute');
end;$$;
select 'PASS: speaker/OOC switching preserves author, participant validation, owner narrator delete/undo without state replay, hidden narrator anchors, deleted pending exclusion, stale reply rejection and player permission limits' as result;
rollback;
